BEGIN TRANSACTION;
CREATE TABLE authority_log (seq INTEGER PRIMARY KEY, prev_hash TEXT NOT NULL, record TEXT NOT NULL, signer_fp TEXT NOT NULL, signature TEXT NOT NULL, hash TEXT NOT NULL UNIQUE);
CREATE TABLE effects ( operation_id TEXT NOT NULL REFERENCES pendings(pending_id), idx INTEGER NOT NULL, store TEXT NOT NULL, resource_key TEXT NOT NULL, pre_image TEXT, native_id TEXT, status TEXT NOT NULL CHECK (status IN ('PLANNED','APPLIED','UNAPPLIED')), reason TEXT, applied_at TEXT, attempts INTEGER NOT NULL DEFAULT 0, next_attempt_at TEXT, last_fault TEXT, PRIMARY KEY (operation_id, idx));
INSERT INTO "effects" VALUES('cp0b3334b961e6f5dff530c442197cec83',0,'spores','spore:ck.0b3334b961e6f5dff530c442197cec83.0',NULL,NULL,'PLANNED',NULL,NULL,0,NULL,NULL);
INSERT INTO "effects" VALUES('cpd6489ad455f8abc0935b1e98ef53020e',0,'spores','spore:k.i','{"disposition":"agenda","domain":"","text":"iota"}',NULL,'PLANNED',NULL,NULL,0,NULL,NULL);
CREATE TABLE labels ( resource_key TEXT NOT NULL, field TEXT NOT NULL, operation_id TEXT NOT NULL, value_sha256 TEXT NOT NULL, decision_kind TEXT NOT NULL, signer_fp TEXT, credential TEXT, fired_at TEXT NOT NULL, epoch INTEGER NOT NULL, PRIMARY KEY (resource_key, field, operation_id));
CREATE TABLE meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
INSERT INTO "meta" VALUES('format','levain-cockpit/3');
INSERT INTO "meta" VALUES('epoch','1');
INSERT INTO "meta" VALUES('label_rev','1');
INSERT INTO "meta" VALUES('install_class','reported');
CREATE TABLE pair_offers ( code_hash TEXT PRIMARY KEY, label TEXT NOT NULL, minted_by TEXT NOT NULL, expires TEXT NOT NULL, used_at TEXT);
CREATE TABLE pair_short_offer ( slot INTEGER PRIMARY KEY CHECK (slot = 1), code_hash TEXT NOT NULL, label TEXT NOT NULL, minted_by TEXT NOT NULL, expires TEXT NOT NULL, used_at TEXT, misses INTEGER NOT NULL DEFAULT 0);
CREATE TABLE paired_devices ( id TEXT PRIMARY KEY, label TEXT NOT NULL, token_hash TEXT NOT NULL UNIQUE, created TEXT NOT NULL, last_seen TEXT, revoked_at TEXT, paired_by TEXT NOT NULL);
CREATE TABLE pendings ( pending_id TEXT PRIMARY KEY, harness TEXT NOT NULL DEFAULT 'cockpit', principal TEXT NOT NULL, principal_base TEXT NOT NULL, idempotency_key TEXT NOT NULL, verb TEXT NOT NULL, tier TEXT NOT NULL, intent TEXT NOT NULL CHECK (intent IN ('sign','reported')), record BLOB NOT NULL, record_sha256 TEXT NOT NULL, issued_at TEXT NOT NULL, expires_at TEXT NOT NULL, state TEXT NOT NULL CHECK (state IN ('WAITING','DECIDED','COMMITTED','COMMITTED_INCOMPLETE',  'STALE','REFUSED','EXPIRED','CANCELLED')), decision_kind TEXT CHECK (decision_kind IN ('ALLOWED','ALLOWED_REPORTED')), decided_at TEXT, signer_fp TEXT, signer_enrolled_at TEXT, signature TEXT, credential TEXT, reason TEXT, cancelled_by TEXT, terminal_at TEXT, UNIQUE (principal_base, idempotency_key));
INSERT INTO "pendings" VALUES('cp0b3334b961e6f5dff530c442197cec83','cockpit','token:browser:1','token:browser','idem-h','spore_seed','T2','reported',X'','093aafe8f38d82745a9d3580f6fcd7601b749e1d407da7d179cf94d0c96b446b','2026-11-11T22:38:12.224759Z','2026-11-11T22:53:12.224759Z','DECIDED','ALLOWED_REPORTED','2026-11-11T22:38:12.237029Z',NULL,NULL,NULL,'token:browser:1',NULL,NULL,NULL);
INSERT INTO "pendings" VALUES('cpd6489ad455f8abc0935b1e98ef53020e','cockpit','token:browser:1','token:browser','idem-i','spore_set_disposition','T2','reported',X'','c82e5111370ddf33fc8c8ce9c5734bca4411adf792550cb9e6654bed9196d7c0','2026-11-11T22:38:12.379283Z','2026-11-11T22:53:12.379283Z','DECIDED','ALLOWED_REPORTED','2026-11-11T22:38:12.391649Z',NULL,NULL,NULL,'token:browser:1',NULL,NULL,NULL);
CREATE TABLE tokens (name TEXT PRIMARY KEY, generation INTEGER NOT NULL);
INSERT INTO "tokens" VALUES('browser',1);
CREATE INDEX pendings_waiting ON pendings (state, expires_at);
CREATE INDEX labels_lookup ON labels (resource_key, field, value_sha256);
CREATE INDEX effects_applied ON effects (applied_at DESC, operation_id, idx) WHERE status = 'APPLIED';
CREATE TRIGGER label_rev_on_label AFTER INSERT ON labels BEGIN UPDATE meta SET value = CAST(CAST(value AS INTEGER) + 1 AS TEXT) WHERE key = 'label_rev'; END;
CREATE TRIGGER label_rev_on_authority AFTER INSERT ON authority_log BEGIN UPDATE meta SET value = CAST(CAST(value AS INTEGER) + 1 AS TEXT) WHERE key = 'label_rev'; END;
CREATE TRIGGER label_rev_on_meta_insert AFTER INSERT ON meta WHEN NEW.key IN ('epoch', 'install_class') BEGIN UPDATE meta SET value = CAST(CAST(value AS INTEGER) + 1 AS TEXT) WHERE key = 'label_rev'; END;
CREATE TRIGGER label_rev_on_meta_update AFTER UPDATE ON meta WHEN NEW.key IN ('epoch', 'install_class') OR OLD.key IN ('epoch', 'install_class') BEGIN UPDATE meta SET value = CAST(CAST(value AS INTEGER) + 1 AS TEXT) WHERE key = 'label_rev'; END;
CREATE TRIGGER label_rev_rises BEFORE UPDATE ON meta WHEN OLD.key = 'label_rev' BEGIN SELECT RAISE(ABORT, 'meta.label_rev only rises, as a canonical integer') WHERE NEW.key IS NOT 'label_rev' OR typeof(NEW.value) IS NOT 'text' OR CAST(NEW.value AS INTEGER) || '' IS NOT NEW.value OR CAST(NEW.value AS INTEGER) <= CAST(OLD.value AS INTEGER); END;
CREATE TRIGGER meta_keeps_its_authority BEFORE DELETE ON meta WHEN OLD.key IN ('epoch', 'install_class', 'label_rev') BEGIN SELECT RAISE(ABORT, 'meta epoch, install_class and label_rev are never deleted'); END;
CREATE TRIGGER labels_immutable_update BEFORE UPDATE ON labels BEGIN SELECT RAISE(ABORT, 'a label row is immutable'); END;
CREATE TRIGGER labels_immutable_delete BEFORE DELETE ON labels BEGIN SELECT RAISE(ABORT, 'a label row is immutable'); END;
CREATE TRIGGER pendings_authority_immutable BEFORE UPDATE ON pendings WHEN NEW.record IS NOT OLD.record OR NEW.record_sha256 IS NOT OLD.record_sha256 OR (OLD.decision_kind IS NOT NULL AND NEW.decision_kind IS NOT OLD.decision_kind) OR (OLD.signer_fp IS NOT NULL AND NEW.signer_fp IS NOT OLD.signer_fp) OR (OLD.credential IS NOT NULL AND NEW.credential IS NOT OLD.credential) OR (OLD.decided_at IS NOT NULL AND NEW.decided_at IS NOT OLD.decided_at) BEGIN SELECT RAISE(ABORT, 'a pending''s record and decision are written once'); END;
COMMIT;
